import{_ as i,o,c as t,an as a}from"./chunks/framework.Bh7I58fu.js";const u=JSON.parse('{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes.md","filePath":"release-notes.md","lastUpdated":null}'),r={name:"release-notes.md"};function s(l,e,n,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="Release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#Release-notes" aria-label="Permalink to &quot;Release notes {#Release-notes}&quot;">​</a></h1><p>Every release of this package is published as a GitHub release. The most recent are reproduced below, as they were written there.</p><h2 id="v0.4.0" tabindex="-1">v0.4.0 <a class="header-anchor" href="#v0.4.0" aria-label="Permalink to &quot;v0.4.0 {#v0.4.0}&quot;">​</a></h2><p>Released 2026-08-06. <a href="https://github.com/EpiAware/ConvolvedDistributions.jl/releases/tag/v0.4.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p><a href="https://github.com/EpiAware/ConvolvedDistributions.jl/compare/v0.3.1...v0.4.0" target="_blank" rel="noreferrer">Diff since v0.3.1</a></p><h5 id="Breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#Breaking-changes" aria-label="Permalink to &quot;Breaking changes {#Breaking-changes}&quot;">​</a></h5><ul><li>The continuous-delay error gate in <code>convolve_series</code> has been removed. A continuous delay is now a plain <code>MethodError</code> where it was previously a checked <code>ArgumentError</code>.</li></ul><h5 id="New-types" tabindex="-1">New types <a class="header-anchor" href="#New-types" aria-label="Permalink to &quot;New types {#New-types}&quot;">​</a></h5><ul><li><strong><code>Ratio</code></strong> type and <code>ratio</code> verb (<code>Z = X / Y</code>): the ratio of two independent non-negative distributions, using Gauss–Legendre quadrature. Supports <code>pdf</code>, <code>cdf</code>, <code>quantile</code>, <code>rand</code>, <code>minimum</code>/<code>maximum</code>, and all AD backends.</li></ul><h5 id="New-features" tabindex="-1">New features <a class="header-anchor" href="#New-features" aria-label="Permalink to &quot;New features {#New-features}&quot;">​</a></h5><ul><li><p><strong><code>pgf</code></strong> — probability generating function primitive for discrete distributions, with closed forms for standard count families (<code>Poisson</code>, <code>Bernoulli</code>, <code>Binomial</code>, <code>Geometric</code>, <code>NegativeBinomial</code>) and a truncated-series fallback for any <code>DiscreteUnivariateDistribution</code>.</p></li><li><p><strong><code>quantile_by_optimization</code></strong> — shared numeric quantile inversion, usable from downstream packages and from the <code>ConvolvedDistributionsOptimizationExt</code> extension for <code>Convolved</code>, <code>Difference</code>, <code>Product</code>, and <code>Ratio</code>.</p></li><li><p><strong>Time-varying delays</strong> — <code>convolve_series</code> now accepts a vector of per-time-point delays (or delay-mass pairs), dispatching element-by-element. Supports both discrete and caller-supplied mass vectors.</p></li></ul><h5 id="Refactoring" tabindex="-1">Refactoring <a class="header-anchor" href="#Refactoring" aria-label="Permalink to &quot;Refactoring {#Refactoring}&quot;">​</a></h5><ul><li><p>Internal renames: <code>_causal_convolve</code> → <code>_convolve_series_fixed</code>, <code>_convolve_series</code> → <code>_convolve_series_varying</code></p></li><li><p>The <code>masses</code> hook is now public API.</p></li></ul><h5 id="Documentation" tabindex="-1">Documentation <a class="header-anchor" href="#Documentation" aria-label="Permalink to &quot;Documentation {#Documentation}&quot;">​</a></h5><ul><li><p>New product-distributions tutorial page</p></li><li><p>PGF documentation in the module docstring</p></li><li><p>FAQ entries for dispatch and solver selection</p></li></ul><h5 id="Maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#Maintenance" aria-label="Permalink to &quot;Maintenance {#Maintenance}&quot;">​</a></h5><ul><li><p>Dependency updates (JET, GitHub Actions)</p></li><li><p>Version increment: 0.3.2 → 0.4.0</p></li></ul><p><strong>Merged pull requests:</strong></p><ul><li><p>chore: auto-increment version to 0.3.2 (#123) (@github-actions[bot])</p></li><li><p>ci(deps): bump the github-actions group with 9 updates (#128) (@dependabot[bot])</p></li><li><p>chore(deps): update JET requirement from 0.9, 0.10, 0.11 to 0.9, 0.10, 0.11, 0.12 in the julia group (#129) (@dependabot[bot])</p></li><li><p>Time-varying delays for <code>convolve_series</code>, and drop the continuous error gate (#126, #95) (#130) (@seabbs-bot)</p></li><li><p>feat: shared numeric quantile inversion, quantile_by_optimization (#112) (#131) (@seabbs-bot)</p></li><li><p>feat: add pgf primitive (#90) (#134) (@seabbs-bot)</p></li><li><p>feat!: solver dispatch for analytic pairs and exact discrete support (#137) (@seabbs-bot)</p></li><li><p>feat: add the Ratio type and ratio verb (Z = X / Y) (#140) (@seabbs-bot)</p></li><li><p>fix: exact fold for two-component mixed discrete/continuous combinations (#142) (@seabbs-bot)</p></li><li><p>chore: bump version to 0.4.0 (#143) (@seabbs-bot)</p></li></ul><p><strong>Closed issues:</strong></p><ul><li><p>Apply my readme style changes across our managed ecosystem (#69)</p></li><li><p>Host the analytic-pair registry + direct CDF-kernel solver (foundation for Censored#891) (#77)</p></li><li><p>Convolved hardcodes Continuous value support — discrete⊛discrete is mis-typed and blocks direct convolve_series (#85)</p></li><li><p>Exact discrete branch in the combination algebra (#89)</p></li><li><p>Probability generating function interface, iteration and fixed points (#90)</p></li><li><p>Remove the continuous-only error gate on convolve_series (#95)</p></li><li><p>_quantile_optimization is duplicated with CensoredDistributions — pick a shared home (#112)</p></li><li><p>docs/src/overall_trend.png is a build artefact but not gitignored (#114)</p></li><li><p>Add a <code>ratio</code> verb for Z = X / Y (#118)</p></li><li><p>TagBot: Manual intervention needed for releases (#124)</p></li><li><p>Support a vector of distributions for convolve_series (#126)</p></li><li><p>Product and ratio introduced with fluff text as if different from other operators (#141)</p></li></ul><h2 id="v0.3.1" tabindex="-1">v0.3.1 <a class="header-anchor" href="#v0.3.1" aria-label="Permalink to &quot;v0.3.1 {#v0.3.1}&quot;">​</a></h2><p>Released 2026-07-31. <a href="https://github.com/EpiAware/ConvolvedDistributions.jl/releases/tag/v0.3.1" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p><a href="https://github.com/EpiAware/ConvolvedDistributions.jl/compare/v0.3.0...v0.3.1" target="_blank" rel="noreferrer">Diff since v0.3.0</a></p><p>Streamlines docs and improves handling of survival distributions</p><h2 id="v0.3.0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0.3.0" aria-label="Permalink to &quot;v0.3.0 {#v0.3.0}&quot;">​</a></h2><p>Released 2026-07-31. <a href="https://github.com/EpiAware/ConvolvedDistributions.jl/releases/tag/v0.3.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p><a href="https://github.com/EpiAware/ConvolvedDistributions.jl/compare/v0.2.0...v0.3.0" target="_blank" rel="noreferrer">Diff since v0.2.0</a></p><p><strong>Merged pull requests:</strong></p><ul><li><p>chore: auto-increment version to 0.2.1 (#46) (@github-actions[bot])</p></li><li><p>docs: add Plots dependency for the benchmark trend plot (#53) (@seabbs-bot)</p></li><li><p>docs: point at the real org setup guide, fix stale Discussions links (#65) (@seabbs-bot)</p></li><li><p>docs: motivation-framed Why bullets, add a Related packages section (#66) (@seabbs-bot)</p></li><li><p>fix!: remove discretise_pmf (#73) (@seabbs-bot)</p></li><li><p>docs: split the visualising-convolutions tutorial per operator (#74) (@seabbs-bot)</p></li><li><p>test: reconcile #50 with its actual fix (#49) (#75) (@seabbs-bot)</p></li><li><p>test: cover Distributions.jl&#39;s censored() composing over the family (#76) (@seabbs-bot)</p></li><li><p>ci: qualify the scaffold_update call ahead of the kit&#39;s export-to-public move (#78) (@seabbs-bot)</p></li><li><p>ci: bump downgrade-compat&#39;s Julia pin to unblock Dependabot PRs (#83) (@seabbs-bot)</p></li><li><p>feat!: retire DelayPMF, accept plain vectors and DiscreteNonParametric (#87) (@seabbs-bot)</p></li><li><p>test: cross-method consistency suite for Convolved/Difference/Product (#57) (#93) (@seabbs-bot)</p></li><li><p>feat: queryable evaluation path with no silent numeric fallback (#92) (#96) (@seabbs-bot)</p></li><li><p>ci: group Dependabot updates and repair template sync (#106) (@seabbs-bot)</p></li><li><p>Update Project.toml (#107) (@seabbs)</p></li><li><p>ci(deps): bump the github-actions group across 1 directory with 12 updates (#108) (@dependabot[bot])</p></li><li><p>chore(deps): bump the julia group with 2 updates (#109) (@dependabot[bot])</p></li></ul><p><strong>Closed issues:</strong></p><ul><li><p>0.2.0 (unregistered) breaks resolution against ComposedDistributions 0.1 — ecosystem is unresolvable (#47)</p></li><li><p>Batched parameter gradients drift from the scalar path at the batch&#39;s left edge (#50)</p></li><li><p>Add downstream migration guidance for the convolve_series discretise-first change (#51)</p></li><li><p>Documenter deploy build crashes: inventory entry for an anchored header with an empty anchor id (#52)</p></li><li><p>TagBot: Manual intervention needed for releases (#61)</p></li><li><p>discretise_pmf is incorrect and we should not have it in the package (#68)</p></li><li><p>Visualise convolutions is heavily overloaded as a docs page (#70)</p></li><li><p>Integrals extension as in CensoredDistributions (#71)</p></li><li><p>censored support (#72)</p></li><li><p>Retire DelayPMF from the public surface: accept plain pmf vectors and DiscreteNonParametric (#79)</p></li></ul><h2 id="v0.2.0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0.2.0" aria-label="Permalink to &quot;v0.2.0 {#v0.2.0}&quot;">​</a></h2><p>Released 2026-07-18. <a href="https://github.com/EpiAware/ConvolvedDistributions.jl/releases/tag/v0.2.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p>0.2.0. Breaking: <code>convolve_series</code> no longer discretises continuous delays (discretise explicitly via <code>discretise_pmf</code> or CensoredDistributions.jl double-interval-censored masses); family renames (<code>AbstractCombinedDistribution</code> → <code>AbstractConvolvedDistribution</code>, <code>test_combined_interface</code> → <code>test_convolved_interface</code>); the AD-safe hook family and tape-strip pair moved to EpiAwareADTools.jl under underscore-free names. Additions: <code>product</code>/<code>Product</code> (Mellin convolution), <code>DelayPMF</code> with grid-width semantics, quantile-panelled quadrature (heavy-tail accuracy), batched-path AD on all six backends, far-tail-accurate extension <code>quantile</code>, nested-composite windows. Full notes in NEWS.md.</p><p><strong>Merged pull requests:</strong></p><ul><li><p>chore: scaffold package with EpiAwarePackageTools (ad=true) (#17) (@seabbs-bot)</p></li><li><p>feat: port raw-distribution convolution + shared quadrature (#18) (@seabbs-bot)</p></li><li><p>chore: auto-increment version to 0.1.1 (#19) (@github-actions[bot])</p></li><li><p>chore: auto-increment version to 0.1.2 (#22) (@github-actions[bot])</p></li><li><p>chore: auto-increment version to 0.1.3 (#23) (@github-actions[bot])</p></li><li><p>feat: add _pdf_ad_safe extension hook for component densities (#27) (@seabbs-bot)</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/coverage.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#33) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/format-check.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#34) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/docs-preview-cleanup.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#35) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/documentation.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#36) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/tagbot.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#37) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/cancel-on-close.yml from 6d4e35e2515f947acbf7d2a683cbf02b341005c7 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#38) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/tests.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#39) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/ad.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#40) (@dependabot[bot])</p></li><li><p>ci(deps): bump EpiAware/.github/.github/workflows/downgrade.yml from dc919e0d1674c16d1518df07eda5ee0be09b47e2 to 6fcdcde033ec670ac3832b239427fd2ded591bbc (#41) (@dependabot[bot])</p></li><li><p>chore: scaffold_update convergence onto kit main + adopt AD-backends tutorial (#54) (@seabbs-bot)</p></li><li><p>feat: public components(::Convolved) accessor (#58) (@seabbs-bot)</p></li><li><p>fix: https:// scheme in docs deploy_url (CSS 404 hotfix) (#59) (@seabbs-bot)</p></li></ul><p><strong>Closed issues:</strong></p><ul><li><p>Scaffold with EpiAwarePackageTools (ad=true) (#1)</p></li><li><p>Port Convolved + public convolve_distributions (#2)</p></li><li><p>Port Difference (X−Y dual) (#3)</p></li><li><p>Port shared quadrature + solver abstraction (#4)</p></li><li><p>AD extensions for Convolved/Difference (#5)</p></li><li><p>Internal timeseries convolve (convolve_with_vector) — deferred/tracking (#6)</p></li><li><p>Restore quantile (inverse-CDF) for Convolved/Difference via an Optimization extension (#20)</p></li><li><p>Add CODECOV_TOKEN repo secret (coverage upload fails on protected main) (#21)</p></li><li><p>Reintroduce combination abstract supertype (AbstractCombinedDistribution) (#24)</p></li><li><p>Decide: adopt docs_subdomain like the sibling packages? (#26)</p></li><li><p>Port the build-once DelayPMF surface (discretise_pmf / pdf / convolve_distributions(pmf, series)) (#28)</p></li><li><p>Batched logpdf disagrees with scalar logpdf by ~1e-3 (shared quadrature window) (#29)</p></li><li><p>Registrator (#30)</p></li><li><p>Discretisation of delays (#31)</p></li><li><p>Docs should show composing on multiple dists (#32)</p></li><li><p>Decide: public surface for _primal / _primal_distribution (ModifiedDistributions extends them) (#42)</p></li><li><p>Batched cdf/pdf/logpdf error under AD with respect to distribution parameters (#43)</p></li><li><p>Batched composite quadrature path has no AD-tag coverage; ReverseDiff w.r.t. evaluation points throws (#44)</p></li><li><p>cdf(::Difference, ::Real) throws _primal(::Tuple) MethodError when ForwardDiff is loaded (#45)</p></li><li><p>Extension quantile is imprecise in far tails (flat squared-residual objective) (#48)</p></li><li><p>Numeric quadrature loses accuracy when a heavy-tailed component stretches the integration window (#49)</p></li><li><p>Add a LoweredDistributions bridge: lower(::Convolved) → dynamical-systems spec (#55)</p></li><li><p>Add a Turing fitting tutorial and MCMC integration test (#56)</p></li></ul><p>Every release, including any older than those above, is listed on the <a href="https://github.com/EpiAware/ConvolvedDistributions.jl/releases" target="_blank" rel="noreferrer">releases page</a>.</p>',40)])])}const h=i(r,[["render",s]]);export{u as __pageData,h as default};
